// ─── File: src/test/java/com/bank/wsy/WaitSleepYieldTest.java ───
package com.bank.wsy;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class WaitSleepYieldTest {

    // ═══ wait() RELEASES lock ═══
    @Test
    void wait_releasesLock() throws InterruptedException {
        Object lock = new Object();
        boolean[] otherGotLock = {false};
        CountDownLatch waiting = new CountDownLatch(1);

        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                waiting.countDown();
                try { lock.wait(2000); } catch (InterruptedException e) { }
            }
        });
        waiter.start();
        waiting.await();
        Thread.sleep(50);

        // waiter is in wait() → lock RELEASED → we CAN enter!
        synchronized (lock) {
            otherGotLock[0] = true;
            lock.notify();
        }
        waiter.join();
        assertThat(otherGotLock[0]).isTrue();  // got the lock while waiter was waiting!
    }

    // ═══ sleep() does NOT release lock ═══
    @Test
    void sleep_doesNotReleaseLock() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch sleeping = new CountDownLatch(1);

        Thread sleeper = new Thread(() -> {
            synchronized (lock) {
                sleeping.countDown();
                try { Thread.sleep(500); } catch (InterruptedException e) { }
            }
        });
        sleeper.start();
        sleeping.await();
        Thread.sleep(50);

        // sleeper is in sleep() → lock NOT released → we are BLOCKED!
        long start = System.currentTimeMillis();
        synchronized (lock) {
            // reached only AFTER sleeper's sleep finishes!
        }
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isGreaterThanOrEqualTo(300);  // blocked ~500ms!
        sleeper.join();
    }

    // ═══ wait() outside synchronized → IMSE ═══
    @Test
    void wait_outsideSync_throwsIMSE() {
        Object lock = new Object();
        assertThatThrownBy(() -> lock.wait())
            .isInstanceOf(IllegalMonitorStateException.class);
    }

    // ═══ sleep() can be called anywhere ═══
    @Test
    void sleep_canBeCalledAnywhere() throws InterruptedException {
        long start = System.currentTimeMillis();
        Thread.sleep(100);
        long elapsed = System.currentTimeMillis() - start;
        assertThat(elapsed).isGreaterThanOrEqualTo(90);
    }

    // ═══ yield() — hint only, no guarantee ═══
    @Test
    void yield_isJustAHint() {
        // yield() returns immediately — no blocking, no waiting
        long start = System.nanoTime();
        Thread.yield();
        long elapsed = System.nanoTime() - start;
        // Should be near-instant — yield is a hint, not a pause
        assertThat(elapsed).isLessThan(10_000_000);  // < 10ms
    }
}
